/**
 * Font Awesome icon picker
 * Lets the user search Font Awesome Free icons and copy their plain HTML (<span>)
 * or Smarty ({!"glyph"|icon}) code to the clipboard
 * Adds button to MD editor
 *
 * Dependencies:
 *
 * _fa_iconpicker.scss
 * _fa_iconpicker_modal.tpl
 * public/admin/dist/data/fa_icons.json (generated by "generate-fa-icons-admin" gulp task)
 * Bootstrap 4+
 */
window.UTILS = window.UTILS || { };

window.UTILS.FAIconpicker = class {

  static IconsList = null;
  static IconsListPromise = null;

  constructor() {
    if ( window.UTILS.FAIconpicker.instance ) {
      window.UTILS.FAIconpicker.instance.attachToolbarButtons();
      return window.UTILS.FAIconpicker.instance;
    }
    window.UTILS.FAIconpicker.instance = this;

    this.modal = document.getElementById( "fa_iconpicker_modal" );
    this.thumbnailTemplate = document.getElementById( "fa_iconpicker_thumbnail" );
    this.thumbnailsContainer = this.modal.querySelector( ".fa-iconpicker__thumbnails" );
    this.searchInput = this.modal.querySelector( "#fa_iconpicker_search_input" );

    this.attachToolbarButtons();

    this.searchInput.addEventListener( "input", this.filterThumbnails.bind( this ) );
    this.thumbnailsContainer.addEventListener( "click", this.onThumbnailsClick.bind( this ) );

    // Bootstrap 4's modal events are jQuery-only (not native DOM events), while
    // Bootstrap 5 dispatches them as native DOM events
    let resetSearch = () => {
      this.searchInput.value = "";
      this.filterThumbnails();
    };
    if ( window.bootstrapVersion === 5 ) {
      this.modal.addEventListener( "show.bs.modal", resetSearch );
    } else {
      window.jQuery( this.modal ).on( "show.bs.modal", resetSearch );
    }

    this.loadIconsList().then( ( icons ) => {
      this.renderThumbnails( icons );
    } );
  }

  /**
   * Create Icons button in toolbars of all MD editors currently in the page
   * Skips editors that already have the button (avoids duplicates when called again
   * after a form replacement)
   */
  attachToolbarButtons() {
    window.UTILS.MDEditorToolbarHelper.addToolbarButton( {
      name: "fa_iconpicker",
      text: "<i class=\"fa-solid fa-icons\"></i> Icons",
      title: "Icons",
      className: "",
      hasModal: true,
      modalId: "#fa_iconpicker_modal",
    } );
    /*document.querySelectorAll( ".md-container" ).forEach( el => {
      if ( el.dataset.faiconpickerbtn ) {
        return;
      }
      this.createToolbarButton( el );
      el.dataset.faiconpickerbtn = "1";
    } );*/
  }

  /**
   * Creates the "Icons" toolbar button for a given markdown editor
   */
  createToolbarButton( el ) {
    let toolbar = el.querySelector( ".md-toolbar .btn-toolbar" );
    let btn = document.createElement( "button" );
    btn.type = "button";
    btn.className = "md-btn btn btn-default md-btn--icon";
    btn.title = "Icons";
    btn.innerHTML = "<i class=\"fa-solid fa-icons\"></i> Icons";
    btn.setAttribute ("data-bs-toggle", "modal");
    btn.setAttribute ("data-toggle", "modal");
    btn.setAttribute ("data-bs-target", "#fa_iconpicker_modal");
    btn.setAttribute ("data-target", "#fa_iconpicker_modal");
    let div = document.createElement( "div" );
    div.className = "button-group";
    div.appendChild( btn );
    toolbar.appendChild( div );
  }

  /**
   * Fetches the list of available Font Awesome Free icons
   * (generated at build time by the "generate-fa-icons-admin" gulp task)
   * Cached on the class so it's only fetched once
   * @returns {Promise<Array>}
   */
  loadIconsList() {
    if ( window.UTILS.FAIconpicker.IconsList ) {
      return Promise.resolve( window.UTILS.FAIconpicker.IconsList );
    }
    if ( !window.UTILS.FAIconpicker.IconsListPromise ) {
      window.UTILS.FAIconpicker.IconsListPromise = fetch( "/public/admin/dist/data/fa_icons.json" )
        .then( ( response ) => response.json() )
        .then( ( icons ) => {
          window.UTILS.FAIconpicker.IconsList = icons;
          return icons;
        } );
    }
    return window.UTILS.FAIconpicker.IconsListPromise;
  }

  /**
   * Renders a thumbnail card for every icon/style combination
   * @param {Array} icons
   */
  renderThumbnails( icons ) {
    let fragment = document.createDocumentFragment();
    icons.forEach( ( icon ) => {
      icon.styles.forEach( ( style ) => {
        fragment.appendChild( this.createThumbnail( icon, style ) );
      } );
    } );
    this.thumbnailsContainer.innerHTML = "";
    this.thumbnailsContainer.appendChild( fragment );
  }

  /**
   * Builds a single thumbnail card for an icon/style combination
   * @param {Object} icon - { glyph, label, terms }
   * @param {String} style - "solid"|"regular"|"brands"
   * @returns {Element}
   */
  createThumbnail( icon, style ) {
    let card = this.thumbnailTemplate.content.firstElementChild.cloneNode( true );
    let styleClass = "fa" + style.charAt( 0 ); // "solid" -> "fas", "regular" -> "far", "brands" -> "fab"
    let iconClass = styleClass + " fa-" + icon.glyph;

    card.dataset.searchtext = [ icon.glyph, icon.label, icon.terms ].join( " " ).toLowerCase();

    card.querySelector( ".card-img-top" ).innerHTML = `<i class="${ iconClass }" aria-hidden="true"></i>`;
    card.querySelector( ".icon_name" ).textContent = style === "solid" ? icon.glyph : `${ icon.glyph } (${ style })`;
    card.querySelector( ".icon_html_code" ).textContent = `<span class="${ iconClass }" aria-hidden="true"></span>`;
    let smartyCodeEl = card.querySelector( ".icon_smarty_code" ); // only present when $DEVELOPMENT
    if ( smartyCodeEl ) {
      smartyCodeEl.textContent = style === "solid"
        ? `{!"${ icon.glyph }"|icon}`
        : `{!"${ icon.glyph }"|icon:"${ style }"}`;
    }

    return card;
  }

  /**
   * Shows/hides thumbnails depending on the search input value
   */
  filterThumbnails() {
    let term = this.searchInput.value.trim().toLowerCase();
    this.thumbnailsContainer.querySelectorAll( ".card--iconthumbnail" ).forEach( ( card ) => {
      card.hidden = term !== "" && !card.dataset.searchtext.includes( term );
    } );
  }

  /**
   * Handles clicks on the copy buttons within thumbnail cards (event delegation)
   */
  onThumbnailsClick( event ) {
    let button = event.target.closest( ".js--copy-html-btn, .js--copy-smarty-btn" );
    if ( !button ) {
      return;
    }
    let card = button.closest( ".card--iconthumbnail" );
    let codeSelector = button.classList.contains( "js--copy-html-btn" ) ? ".icon_html_code" : ".icon_smarty_code";
    let code = card.querySelector( codeSelector ).textContent;

    this.setClipboard( code );
    this.showCopiedFeedback( button );
  }

  /**
   * Briefly shows a "Copied!" confirmation on the clicked button
   * @param {Element} button
   */
  showCopiedFeedback( button ) {
    let originalText = button.textContent;
    button.textContent = window.faIconpickerTexts && window.faIconpickerTexts.copied || "Copied!";
    window.setTimeout( () => {
      button.textContent = originalText;
    }, 1000 );
  }

  /**
   * Puts given text to clipboard
   * @param {String} text
   */
  async setClipboard( text ) {
    const type = "text/plain";
    const clipboardItemData = {
      [ type ]: text,
    };
    // eslint-disable-next-line no-undef
    const clipboardItem = new ClipboardItem( clipboardItemData );
    await navigator.clipboard.write( [ clipboardItem ] );
  }

};
